mapper.select:
SELECT account_id, linked_at
FROM public.account_telegram_connection
WHERE account_id = #{accountId}

mapper.update:
UPDATE public.telegram_link_token
SET revoked_at = #{revokedAt}
WHERE account_id = #{accountId}
  AND consumed_at IS NULL
  AND revoked_at IS NULL

UPDATE public.attendance_notification_outbox
SET status = 'DEAD', last_error_code = #{errorCode}, lease_until = NULL, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING'

UPDATE public.attendance_notification_outbox
SET status = 'RETRY', lease_until = NULL, next_attempt_at = #{now},
    last_error_code = 'TELEGRAM_LEASE_EXPIRED', updated_at = #{now}
WHERE status = 'PROCESSING' AND lease_until < #{now}
